CREATE TABLE IF NOT EXISTS `xy_card_collection_config`
(
    `id`           BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '自增主键',
    `region_name`  VARCHAR(128) NOT NULL COMMENT '地区名称',
    `sort_order`   INT          NOT NULL DEFAULT 0 COMMENT '地区内排序',
    `monster_id`   INT          NOT NULL COMMENT '怪物ID',
    `card_item_id` INT          NOT NULL COMMENT '卡片物品ID',
    `create_time`  TIMESTAMP             DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `update_time`  TIMESTAMP             DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
    UNIQUE KEY `uk_card_item` (`card_item_id`),
    KEY `idx_region` (`region_name`, `sort_order`)
) COMMENT '卡片收集配置表' ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4;

